import { defineConfig, devices } from "@playwright/test";

/**
 * Kept separate from the logic suite.
 *
 * The main suite (`tests/E2E`) never opens a browser: it is pure rules running
 * under the Playwright runner. This one does, and against a real stack — its
 * own directory, its own timeout and a single browser, because the same layout
 * defect shows up identically in all three.
 *
 * It needs the load stack up and seeded: the API on 3334, Next on 3100, and
 * `tests/load/fixtures/load-context.json` in the API repo, which is gitignored
 * (it holds minted JWTs) and is regenerated by `tests/load/seed.ts`. See
 * `../trajetto-api/tests/load/README.md`.
 */
export default defineConfig({
  testDir: "./tests/responsive",
  fullyParallel: true,
  // CI: the 4-vCPU runner also hosts Postgres, the API and the web server, so
  // fewer browsers at once, and one retry for a timing flake. A real defect
  // fails both attempts and still fails the job; a test that passed only on
  // the retry is listed as "flaky" in the report, not hidden.
  workers: process.env.CI ? 2 : 4,
  retries: process.env.CI ? 1 : 0,
  timeout: 90_000,
  reporter: [["list"]],
  use: {
    ...devices["Desktop Chrome"],
    baseURL: process.env.RESPONSIVE_BASE_URL ?? "http://localhost:3100",
    // The users' browser, not the CI runner's UTC/en-US (see the UI config).
    locale: "pt-BR",
    timezoneId: "America/Sao_Paulo",
  },
});
